beforeEach_source:
test.beforeEach(async ({ page }, testInfo) => {
  const fault = testInfo.project.metadata.fault as string;
  if (fault === "tablet" || fault === "mobile") {
    await page.addInitScript((faultWidth) => {
      document.addEventListener("DOMContentLoaded", () => {
        const style = document.createElement("style");
        style.textContent = `@media (min-width: ${faultWidth}px) and (max-width: ${faultWidth}px) { body { min-width: 1800px !important; } }`;
        document.head.append(style);
      });
    }, fault === "tablet" ? 768 : 375);
  } else if (fault === "hidden" || fault === "href") {
    await page.addInitScript((kind) => {
      new MutationObserver(() => {
        for (const link of document.querySelectorAll<HTMLAnchorElement>('a[href^="/tasks/new?"]')) {
          if (kind === "hidden") link.style.visibility = "hidden";
          else link.setAttribute("href", "/tasks/broken");
        }
      }).observe(document, { childList: true, subtree: true });
    }, fault);
  }
});

